from typing import List

class Solution:
    def eraseOverlapIntervals(self, intervals: List[List[int]]) -> int:
        intervals.sort()
        removals = 0
        current_end = intervals[0][1]

        for start, end in intervals[1:]:
            if start < current_end:
                removals += 1
                current_end = min(current_end, end)
            else:
                current_end = end
        return removals

